-- Curated retrieval metadata for the AI coach's candidate shortlist (src/lib/coach/candidates.ts).
-- movement_pattern groups exercises by the movement they train (also the basis for same-pattern variant swaps);
-- popularity ranks how standard an exercise is: 3 core staple, 2 common staple, 1 default, 0 unusual variant.
ALTER TABLE public.exercises
  ADD COLUMN popularity smallint NOT NULL DEFAULT 1 CHECK (popularity BETWEEN 0 AND 3),
  ADD COLUMN movement_pattern text CHECK (movement_pattern IN ('squat', 'hinge', 'lunge', 'glute_bridge', 'horizontal_push', 'vertical_push', 'horizontal_pull', 'vertical_pull', 'carry', 'core', 'biceps', 'triceps', 'shoulder_iso', 'rear_delt', 'chest_iso', 'leg_iso', 'calf', 'forearm', 'power', 'conditioning', 'mobility'));

COMMENT ON COLUMN public.exercises.popularity IS 'How standard the exercise is: 3 core staple, 2 common staple, 1 default, 0 unusual variant.';
COMMENT ON COLUMN public.exercises.movement_pattern IS 'Movement the exercise trains; NULL when unclassified.';

